// === Feld-Normalisierung · an den eigenen Feed anpassen ===
// Jeder RSS-Feed liefert andere Felder. Hier wird aus Titel und Text
// herausgezogen, was der Vorfilter braucht: Budget, Währung, Art.
const KURS_ZU_USD = { USD:1, EUR:1.08, GBP:1.27, CHF:1.12 }; // grob, reicht zum Filtern

const out = [];
for (const item of $input.all()) {
  const d    = item.json;
  const text = `${d.title || ''} ${d.contentSnippet || d.content || ''}`;

  // Währung erkennen
  let waehrung = 'USD';
  const wSym = text.match(/(₹|€|£|\$)/);
  const wIso = text.match(/\b(USD|EUR|GBP|INR|PKR|BDT|PHP|NGN|LKR|CHF)\b/);
  if (wIso) waehrung = wIso[1].toUpperCase();
  else if (wSym) waehrung = { '₹':'INR', '€':'EUR', '£':'GBP', '$':'USD' }[wSym[1]];

  // Beträge einsammeln, größten als Obergrenze nehmen
  const zahlen = (text.match(/[\d][\d.,]{1,12}/g) || [])
    .map(s => Number(s.replace(/\.(?=\d{3}\b)/g, '').replace(',', '.')))
    .filter(n => !isNaN(n) && n > 0);
  const max = zahlen.length ? Math.max(...zahlen) : 0;

  // Stunden- oder Festpreis
  const proStunde = /\b(hour|hourly|\/\s?hr|per hour|stunde|stundensatz)\b/i.test(text);

  out.push({ json: {
    title:   d.title || '',
    link:    d.link  || '',
    guid:    d.guid  || d.id || d.link || '',
    content: d.contentSnippet || d.content || '',
    currency: waehrung,
    type: proStunde ? 'hourly' : 'fixed',
    budgetUsdMax: Math.round(max * (KURS_ZU_USD[waehrung] || 1))
  }});
}
return out;

// === Job-Radar · Vorfilter v2 ===
// Neu gegenüber v1: Merkliste (nichts wird zweimal gemeldet),
// saubere Typ-Erkennung und eine "knapp verfehlt"-Liste.
const NUR_MARKIEREN    = false;  // true = nichts wegwerfen, nur markieren

const MIN_FESTPREIS_USD = 1600;  // eigene Untergrenze setzen
const MIN_STUNDE_USD    = 43;
const MERKEN_TAGE       = 30;
const KNAPP_ANTEIL      = 0.6;   // ab 60 % der Schwelle = knapp verfehlt
const MAX_KNAPP         = 3;

const RAUS_WAEHRUNG = ['INR','PKR','BDT','PHP','NGN','LKR'];
const RAUS_BEGRIFF  = /\b(review|bewertung|clone|voice.?clone|deepfake|backlink|faceless|follower)\b/i;

const sd      = $getWorkflowStaticData('global');
const gesehen = sd.jobGesehen || (sd.jobGesehen = {});
const jetzt   = Date.now();
const haltbar = MERKEN_TAGE * 24 * 3600 * 1000;

const out = [], knapp = [], zaehler = {};
let neu = 0, bekannt = 0;
const zaehl = k => { zaehler[k] = (zaehler[k] || 0) + 1; };

for (const item of $input.all()) {
  const d = item.json;
  const schluessel = String(d.guid || d.link || d.title || '').trim();
  if (!schluessel)        { zaehl('Ohne Kennung'); continue; }
  if (gesehen[schluessel]) { bekannt++; continue; }   // schon gemeldet

  const text  = `${d.title || ''} ${d.content || ''}`;
  const max   = Number(d.budgetUsdMax) || 0;
  const label = String(d.type || '');

  let proStunde = /hour|stunde/i.test(label);
  let typUnklar = false;
  // Festpreis unter 150 USD ist fast immer ein falsch erkannter Stundensatz
  if (!proStunde && max > 0 && max < 150) { proStunde = true; typUnklar = true; }

  let grund = null;
  if (RAUS_WAEHRUNG.includes(String(d.currency || '').toUpperCase())) grund = 'Währung ' + d.currency;
  else if (max === 0)                             grund = 'Budget unbekannt';
  else if (proStunde && max < MIN_STUNDE_USD)     grund = 'Stundensatz zu niedrig';
  else if (!proStunde && max < MIN_FESTPREIS_USD) grund = 'Budget zu niedrig';
  else if (RAUS_BEGRIFF.test(text))               grund = 'Begriff: ' + text.match(RAUS_BEGRIFF)[0].toLowerCase();

  gesehen[schluessel] = jetzt;
  neu++;
  zaehl(grund || 'durch');

  if (grund === 'Budget zu niedrig' || grund === 'Stundensatz zu niedrig') {
    const schwelle = proStunde ? MIN_STUNDE_USD : MIN_FESTPREIS_USD;
    if (max >= schwelle * KNAPP_ANTEIL) {
      knapp.push({ titel: String(d.title || '').slice(0, 80), usd: max, schwelle, link: d.link || '', typUnklar });
    }
  }

  if (!grund || NUR_MARKIEREN) {
    out.push({ json: { ...d, _raus: !!grund, _raus_grund: grund, _proStunde: proStunde, _typUnklar: typUnklar } });
  }
}

// Merkliste aufräumen
for (const k of Object.keys(gesehen)) if (jetzt - gesehen[k] > haltbar) delete gesehen[k];

knapp.sort((a, b) => (b.usd / b.schwelle) - (a.usd / a.schwelle));

console.log('Vorfilter:', $input.all().length, 'rein |', neu, 'neu |', bekannt, 'bekannt |', out.length, 'durch ->', zaehler);

// Immer genau ein Ergebnis-Objekt für die Meldung mitgeben
return [{ json: {
  treffer: out.map(o => o.json),
  geprueft: $input.all().length,
  neu, bekannt,
  gruende: zaehler,
  knapp: knapp.slice(0, MAX_KNAPP)
}}];

// === Meldung bauen ===
const d = $input.first().json;
const g = d.gruende || {};

const zeilen = Object.entries(g)
  .filter(([k]) => k !== 'durch')
  .sort((a, b) => b[1] - a[1])
  .map(([k, v]) => `${v}× ${k}`);

let t = `<b>Job-Radar</b>\n${d.neu} neu geprüft, ${d.bekannt} schon bekannt, ${g.durch || 0} durch.`;
if (zeilen.length) t += `\n${zeilen.join(' · ')}`;

if (d.treffer && d.treffer.length) {
  t += `\n\n<b>Treffer:</b>`;
  for (const j of d.treffer) {
    t += `\n• ${j.budgetUsdMax} USD – ${String(j.title).slice(0, 90)}\n${j.link}`;
  }
}

if (d.knapp && d.knapp.length) {
  t += `\n\n<b>Knapp verfehlt:</b>`;
  for (const k of d.knapp) {
    t += `\n• ${k.usd} von ${k.schwelle} USD${k.typUnklar ? ' (Typ unklar)' : ''} – ${k.titel}\n${k.link}`;
  }
}

return [{ json: { text: t } }];
